import{_ as a,c as r,o as i,ag as t}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"Learning","description":"","frontmatter":{"title":"Learning","tags":["learning","education","resources","training"]},"headers":[],"relativePath":"general/learning.md","filePath":"general/learning.md","lastUpdated":null}'),o={name:"general/learning.md"};function n(s,e,l,u,c,d){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="learning" tabindex="-1">Learning <a class="header-anchor" href="#learning" aria-label="Permalink to &quot;Learning&quot;">​</a></h1><h2 id="learning-guides-and-resources" tabindex="-1">Learning Guides and Resources <a class="header-anchor" href="#learning-guides-and-resources" aria-label="Permalink to &quot;Learning Guides and Resources&quot;">​</a></h2><p>This page is a comprehensive guide to various educational resources and programs available for military personnel and their families. It includes links to free and discounted courses, technical training, and professional development opportunities across platforms like Udemy, O’Reilly, Coursera, and more. Each section provides key details about the offerings, eligibility, and access instructions, making it easier for service members to enhance their skills and knowledge in various fields.</p><p>If you are looking for resources, guides, and certification funding, see the <a href="/general/certifications.html">Page</a>.</p><p>Find community-shared posts about learning <a href="https://forum.irregularchat.com/tag/learning" target="_blank" rel="noreferrer">here</a></p><h3 id="learning-tools" tabindex="-1">Learning Tools <a class="header-anchor" href="#learning-tools" aria-label="Permalink to &quot;Learning Tools&quot;">​</a></h3><h3 id="ai-enabled-learning" tabindex="-1">AI Enabled Learning <a class="header-anchor" href="#ai-enabled-learning" aria-label="Permalink to &quot;AI Enabled Learning&quot;">​</a></h3><ul><li><a href="https://llamatutor.together.ai" target="_blank" rel="noreferrer">AI Tutor</a></li></ul><h3 id="free-chicken" tabindex="-1">Free Chicken <a class="header-anchor" href="#free-chicken" aria-label="Permalink to &quot;Free Chicken&quot;">​</a></h3><h4 id="harvard-university" tabindex="-1">Harvard University <a class="header-anchor" href="#harvard-university" aria-label="Permalink to &quot;Harvard University&quot;">​</a></h4><ul><li><a href="https://pll.harvard.edu/catalog/free" target="_blank" rel="noreferrer">Free online courses in tech, programming, policy, politics, business, AI/ML, coding, media, history, literature, biology, law, and more.</a></li></ul><h4 id="udemy-for-military" tabindex="-1">Udemy for Military <a class="header-anchor" href="#udemy-for-military" aria-label="Permalink to &quot;Udemy for Military&quot;">​</a></h4><ul><li><a href="https://digitalu.af.mil/" target="_blank" rel="noreferrer">Free if you sign up and verify with a .mil email.</a></li></ul><h4 id="o-reilly" tabindex="-1">O’Reilly <a class="header-anchor" href="#o-reilly" aria-label="Permalink to &quot;O’Reilly&quot;">​</a></h4><ul><li><a href="https://www.oreilly.com/self-registration/dod-mwr-libraries-army/" target="_blank" rel="noreferrer">Technical Books, Videos, and Lessons</a></li></ul><h4 id="microsoft-enterprise-skills" tabindex="-1">Microsoft Enterprise Skills <a class="header-anchor" href="#microsoft-enterprise-skills" aria-label="Permalink to &quot;Microsoft Enterprise Skills&quot;">​</a></h4><ul><li><a href="https://esi.microsoft.com/" target="_blank" rel="noreferrer">Microsoft Enterprise Skills</a></li></ul><h4 id="coursera" tabindex="-1">Coursera <a class="header-anchor" href="#coursera" aria-label="Permalink to &quot;Coursera&quot;">​</a></h4><ul><li><a href="https://www.eventbrite.com/e/no-cost-on-line-coursera-certification-courses-for-military-and-spouse-tickets-165655358637?aff=eemailordconf&amp;ref=eemailordconf&amp;utm_campaign=order_confirm&amp;utm_medium=email&amp;utm_source=eventbrite&amp;utm_term=viewevent" target="_blank" rel="noreferrer">Eventbrite Link</a></li></ul><blockquote></blockquote><p>Filled out the data as it says in the body; took about two days for them to email credentials.</p><h4 id="tutor-com" tabindex="-1">Tutor.com <a class="header-anchor" href="#tutor-com" aria-label="Permalink to &quot;Tutor.com&quot;">​</a></h4><ul><li><a href="http://military.tutor.com/" target="_blank" rel="noreferrer">Free Resource for Service Members and Families</a></li></ul><h4 id="dc3" tabindex="-1">DC3 <a class="header-anchor" href="#dc3" aria-label="Permalink to &quot;DC3&quot;">​</a></h4><ul><li><a href="https://www.dcita.edu/" target="_blank" rel="noreferrer">DC3 Cyber Training Academy</a></li></ul><blockquote></blockquote><p>From computer hardware fundamentals to advanced forensic concepts, the DC3 Cyber Training Academy provides students with the skills needed to meet mission goals in the cyber environment.</p><h4 id="sof-education-program-sep-funds-guide" tabindex="-1">SOF EDUCATION PROGRAM (SEP) FUNDS GUIDE <a class="header-anchor" href="#sof-education-program-sep-funds-guide" aria-label="Permalink to &quot;SOF EDUCATION PROGRAM (SEP) FUNDS GUIDE&quot;">​</a></h4><ul><li><a href="https://u.pcloud.link/publink/show?code=XZ0frk0ZchOJr4ELEVkiFyB7Ic45CmhSpaEk" target="_blank" rel="noreferrer">Download/View Link</a></li></ul><blockquote></blockquote><p>SEP offers up to $10,000 per fiscal year, separate from Tuition Assistance (TA) or Credentialing Assistance (CA). This unique funding focuses on specific knowledge gaps in special operations roles, supporting professional development without duplicating existing service programs. Requests involve submission of forms like SF-182 and must comply with specific criteria, such as no planned separation within 18 months. For more details, contact the Education Office.</p><h4 id="packt" tabindex="-1">PACKT <a class="header-anchor" href="#packt" aria-label="Permalink to &quot;PACKT&quot;">​</a></h4><ul><li><a href="https://www.packtpub.com/free-learning" target="_blank" rel="noreferrer">Free Technical Resources</a></li></ul><h4 id="ccna" tabindex="-1">CCNA <a class="header-anchor" href="#ccna" aria-label="Permalink to &quot;CCNA&quot;">​</a></h4><ul><li><a href="https://www.ccna.ninja/" target="_blank" rel="noreferrer">CCNA Ninja</a></li></ul><blockquote></blockquote><p>Free NetAcad training for CCNA and, if you do well enough on the tests, you can qualify for a 60% voucher. This is also valid for Cisco’s CyberOps Associate. MIT Free Courses</p><p><a href="https://ocw.mit.edu/about/" target="_blank" rel="noreferrer">Collection of free MIT courses 🫡</a></p><h3 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h3><ul><li><p><a href="/general/certifications.html">Guides and Resources</a></p></li><li><p><a href="/cybersecurity/cybersecurity-university-courses.html">Courses</a></p></li></ul><blockquote></blockquote><p>Using educational resources from Hack The Box Academy helps prepare users for intermediate cybersecurity courses like the Offensive Security Certified Professional (OSCP). Registering with a school email reduces the monthly cost from $40 to about $10, saving nearly $370 annually.</p><h3 id="defense-acquisition-university-dau" tabindex="-1">Defense Acquisition University (DAU) <a class="header-anchor" href="#defense-acquisition-university-dau" aria-label="Permalink to &quot;Defense Acquisition University (DAU)&quot;">​</a></h3><p>The <a href="https://www.dau.edu" target="_blank" rel="noreferrer">Defense Acquisition University (DAU)</a> provides online and in-person courses that count as military education and offer professional certifications. DAU is an excellent resource for those looking to meet professional development requirements without budget or approval barriers, as you can designate yourself as your supervisor.</p><h3 id="notable-courses" tabindex="-1">Notable Courses <a class="header-anchor" href="#notable-courses" aria-label="Permalink to &quot;Notable Courses&quot;">​</a></h3><p>Mentioned by David R.</p><ul><li><p><strong>ACQ101 - Acquisitions 101</strong>: Provides foundational acquisition knowledge, including processes and requirements.</p></li><li><p><em>&#39;Source Selection</em>: Covers ethics and techniques for down-selection during source evaluations.</p></li><li><p><em>ETM 3150 - Introduction to Emerging Technology</em>: Focuses on understanding and leveraging new technologies in defense settings.</p></li></ul><h3 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h3><p>DAU credentials fulfill continuing education requirements for certifications like the PMP. Examples include:</p><ul><li><a href="https://www.dau.edu/credentials" target="_blank" rel="noreferrer">Small Business Program Credential</a></li></ul><blockquote></blockquote><p>The Small Business Program Credential enhances understanding of small business participation in acquisitions.</p><p>DAU courses and credentials are a convenient way to stay competitive in professional development while meeting military requirements.</p><p>[Development] [Education]</p>',54)])])}const m=a(o,[["render",n]]);export{f as __pageData,m as default};
